"""tr — virtues_c."""

T = {
"virtues_051": ("Lokman oğluna ses hakkında ne öğütler?", ["Sesini kısmasını: seslerin en çirkini eşeğin sesidir", "Çok yüksek sesle konuşmasını", "Hiç konuşmamasını", "Yürürken şarkı söylemesini"], "«Yürüyüşünde ölçülü ol ve sesini kıs: seslerin en çirkini elbette eşeklerin sesidir»."),
"virtues_052": ("Lokman, sabırdan söz etmeden önce oğluna hangi üç tavsiyede bulunur?", ["Namazı kılmak, iyiliği emretmek, kötülükten sakındırmak", "Seyahat, ticaret, yazı", "Az yemek, az uyumak, az konuşmak", "İnşa, ekim, hasat"], "«Yavrucuğum! Namazı kıl, iyiliği emret, kötülükten sakındır ve başına gelene sabret»."),
"virtues_053": ("Âl-i İmran suresinde Kur'an takva sahiplerine hangi üç vasfı verir?", ["Bollukta ve darlıkta infak, öfkeyi yutma, insanları affetme", "Oruç, gece namazı, sükût", "İnşa, ekim, bağış", "Seyahat, öğrenme, öğretme"], "«Onlar bollukta ve darlıkta infak eder, öfkelerini yutar ve insanları affederler: Allah iyilik yapanları sever»."),
"virtues_054": ("Kur'an, ardından incitme gelen bir sadakadan daha hayırlı gördüğü nedir?", ["Güzel bir söz ve bağışlama", "Daha büyük bir bağış", "Tam bir sessizlik", "Bir yemin"], "«Güzel bir söz ve bağışlama, ardından eziyet gelen bir sadakadan hayırlıdır»."),
"virtues_055": ("Kur'an gizlice verilen sadaka hakkında ne der?", ["Veren için daha hayırlıdır", "Sayılmaz", "Duyurulmalıdır", "Yasaktır"], "«Sadakaları açıktan verirseniz ne güzel; ama onları gizler ve fakirlere verirseniz bu sizin için daha hayırlıdır»."),
"virtues_056": ("Kur'an neyin sadaka olarak verilmesini yasaklar?", ["Kendisinin ancak göz yumarak alacağı kötü şeyin", "Yeni olanın", "Sevilenin", "Mirastan gelenin"], "«Kendinizin göz yummadan alamayacağınız kötü şeyleri vermeye kalkışmayın»."),
"virtues_057": ("Âl-i İmran suresine göre gerçek iyiliğe ne zaman ulaşılır?", ["Sevilen şeyden infak edilerek", "Fazlalıktan infak edilerek", "Açıktan infak edilerek", "Her şeyi tutarak"], "«Sevdiğiniz şeylerden infak etmedikçe iyiliğe erişemezsiniz»."),
"virtues_058": ("Kur'an harcamada dengeyi hangi görüntüyle anlatır?", ["Eli boyna bağlamamak da büsbütün açmamak da", "Kapıyı kapatmak", "Yavaş yürümek", "İki kez saymak"], "«Elini boynuna bağlama, büsbütün de açma; sonra kınanmış ve çaresiz kalırsın»."),
"virtues_059": ("Kur'an «Rahman'ın kullarının» harcamasını nasıl anlatır?", ["Ne israf ne cimrilik; ikisinin arasında dengeli", "Ölçüsüz cömert", "Hep tutumlu", "Hiç vermeyen"], "«Onlar harcadıklarında ne israf ne de cimrilik ederler; ikisi arasında dengeli olurlar»."),
"virtues_060": ("Kur'an kendi evi olmayan bir eve girmeden önce ne emreder?", ["İzin istemeyi ve ev halkına selam vermeyi", "Üç kez vurup girmeyi", "Doğrudan girmeyi", "Uzaktan seslenmeyi"], "«Kendi evlerinizden başka evlere, izin isteyip ev halkına selam vermeden girmeyin»."),
"virtues_061": ("Nur suresine göre ziyaretçiye «dön» denirse ne yapmalıdır?", ["Dönmeli: bu onun için daha temizdir", "Israr etmeli", "Kapıda beklemeli", "Yine de girmeli"], "«Size “dönün” denirse dönün: bu sizin için daha temizdir»."),
"virtues_062": ("Kur'an güvenilmez biri bir haber getirdiğinde ne emreder?", ["Araştırmayı, bilmeden bir topluluğa zarar vermemek için", "Hemen yaymayı", "Yazmayı", "Her zaman görmezden gelmeyi"], "«Size bir fasık haber getirirse onu araştırın; yoksa bilmeden bir topluluğa zarar verir, sonra yaptığınıza pişman olursunuz»."),
"virtues_063": ("Hucurat suresi gıybetle birlikte hangi davranışı yasaklar?", ["Casusluk yapmayı ve aşırı zannı", "Yalnız yolculuk etmeyi", "Alçak sesle konuşmayı", "Mektup yazmayı"], "«Ey iman edenler! Zannın çoğundan kaçının: şüphesiz bazı zan günahtır. Birbirinizin kusurunu araştırmayın ve gıybet etmeyin»."),
"virtues_064": ("Kur'an iki mümin topluluk çarpışırsa ne emreder?", ["Aralarını adaletle bulmayı", "Bir tarafı tutmayı", "Onları görmezden gelmeyi", "Sadece güçle ayırmayı"], "«Müminlerden iki grup birbiriyle savaşırsa aralarını düzeltin… ve adaletli olun: Allah adaletli davrananları sever»."),
"virtues_065": ("Kur'an, nefret edilen bir topluluğa karşı bile açıkça neyi yasaklar?", ["Kinin adaletten saptırmasını", "Ticareti", "Konuşmayı", "Komşuluğu"], "«Bir topluluğa duyduğunuz kin sizi adaletsizliğe sürüklemesin. Adaletli olun: bu takvaya daha yakındır»."),
"virtues_066": ("Kur'an gerekirse kime karşı adaletle şahitlik etmeyi ister?", ["Kendinize, ana babanıza ve yakınlarınıza karşı", "Sadece yabancılara karşı", "Sadece zenginlere karşı", "Sadece fakirlere karşı"], "«Adaleti ayakta tutan ve Allah için şahitlik eden kimseler olun; kendinizin, ana babanızın ve yakınlarınızın aleyhine bile olsa»."),
"virtues_067": ("Kur'an neyin sahiplerine geri verilmesini emreder?", ["Emanetlerin", "Mektupların", "Hasatların", "Anlatıların"], "«Allah size emanetleri ehline vermenizi ve insanlar arasında hükmettiğinizde adaletle hükmetmenizi emreder»."),
"virtues_068": ("4:36 ayeti ana babadan sonra iyilik için hangi kimseleri sayar?", ["Yakınları, yetimleri, yoksulları, yakın ve uzak komşuyu, arkadaşı, yolcuyu ve elinizin altındakini", "Kralları ve reisleri", "Tüccarları", "Sadece âlimleri"], "«Allah'a kulluk edin ve O'na hiçbir şeyi ortak koşmayın. Ana babaya, yakınlara, yetimlere, yoksullara, yakın komşuya, uzak komşuya, yanınızdaki arkadaşa, yolcuya ve elinizin altındakilere iyilik edin»."),
"virtues_069": ("Kur'an darlıktaki bir borçluya karşı ne emreder?", ["Bolluğa kadar süre tanımayı", "Onu takip etmeyi", "Borcu ikiye katlamayı", "Onu kovmayı"], "«Eğer borçlu darlık içindeyse, kolaylığa kadar ona süre tanıyın; sadaka olarak bağışlamanız ise sizin için daha hayırlıdır»."),
"virtues_070": ("Kur'an'ın en uzun ayeti vadeli borç için ne emreder?", ["Onu yazmayı", "Gizli tutmayı", "Unutmayı", "Sözlü aktarmayı"], "«Ey iman edenler! Belirli bir süreye kadar borçlandığınızda onu yazın»."),
"virtues_071": ("Kur'an başkalarının malı hakkında neyi yasaklar?", ["Haksızca yemeyi veya onunla hâkimlere rüşvet vermeyi", "Saymayı", "Satmayı", "Korumayı"], "«Mallarınızı aranızda haksızlıkla yemeyin ve insanların mallarından bir kısmını bile bile günahla yemek için onu hâkimlere aktarmayın»."),
"virtues_072": ("Kur'an yetimlerin malı hakkında ne emreder?", ["Onlara vermeyi, iyiyi kötüyle değiştirmemeyi", "Paylaştırmayı", "Satmayı", "Ömür boyu tutmayı"], "«Yetimlere mallarını verin; temizi pisle değiştirmeyin ve onların mallarını kendi mallarınıza katarak yemeyin»."),
"virtues_073": ("Kur'an ölçmeyi ve tartmayı nasıl emreder?", ["Ölçüyü tam yapmayı ve doğru terazi ile tartmayı", "Kendi lehine yuvarlamayı", "Göz kararı tartmayı", "İki kez ölçmeyi"], "«Ölçtüğünüzde ölçüyü tam yapın ve doğru terazi ile tartın: bu daha hayırlı ve sonuç bakımından daha güzeldir»."),
"virtues_074": ("Kur'an bilgisizce neyin ardına düşmeyi yasaklar?", ["Hakkında bilgi olmayan şeyin: kulak, göz ve kalp bundan sorumludur", "En kısa yolun", "Kervanların", "Sessizliğin"], "«Hakkında bilgin olmayan şeyin ardına düşme: şüphesiz kulak, göz ve kalp, bunların hepsi ondan sorumludur»."),
"virtues_075": ("Kur'an yürüyüşteki kibri hangi görüntüyle anlatır?", ["Yeri yaramaz ve boyca dağlara erişemezsin", "Daha hızlı ilerlersin", "Daha az yorulursun", "Saygı görürsün"], "«Yeryüzünde böbürlenerek yürüme: sen ne yeri yarabilirsin ne de boyca dağlara erişebilirsin»."),
"virtues_076": ("Kur'an, amellerin ıslah edileceğini vaat ederek sözün hangi vasfını emreder?", ["Doğru ve yerinde söz (kavl-i sedîd)", "Kısa söz", "Âlimane söz", "Yazılı söz"], "«Ey iman edenler! Allah'tan korkun ve doğru söz söyleyin: O, işlerinizi düzeltir ve günahlarınızı bağışlar»."),
"virtues_077": ("Kur'an'da bir zorbanın karşısında bile hangi söz emredildi?", ["Yumuşak söz", "Tehditkâr söz", "Alaycı söz", "Sessizlik"], "«Ona yumuşak söz söyleyin: belki öğüt alır veya korkar»."),
"virtues_078": ("Kur'an sözü en güzel olanın kim olduğunu söyler?", ["Allah'a çağıran, salih amel işleyen ve “ben müslümanlardanım” diyen", "Şairin", "Hatibin", "Hâkimin"], "«Allah'a çağıran, salih amel işleyen ve “ben müslümanlardanım” diyenden daha güzel sözlü kim olabilir?»"),
"virtues_079": ("Mü'minûn suresine göre kurtuluşa eren müminler neden yüz çevirir?", ["Boş sözden (lağv)", "İşten", "Yolculuktan", "Yemekten"], "«…ve onlar ki boş sözden yüz çevirirler»."),
"virtues_080": ("Mü'minûn suresine göre kurtuluşa eren müminler hangi iki sorumluluğu gözetir?", ["Kendilerine verilen emanetleri ve ahitlerini", "Orucu ve gece namazını", "Yolculuğu ve ticareti", "Yazmayı ve okumayı"], "«Ve onlar ki emanetlerini ve ahitlerini gözetirler»."),
"virtues_081": ("Kur'an, kötülüğü karşılayabilecekken affedip ıslah edeni nasıl anar?", ["Onun ecri Allah'a aittir", "Hakkını yitirir", "Kınanır", "Susmalıdır"], "«Bir kötülüğün karşılığı ona denk bir kötülüktür; ama kim affeder ve barışı sağlarsa, onun ecri Allah'a aittir»."),
"virtues_082": ("Kur'an bize haksızlık edeni affetmek için hangi gerekçeyi sunar?", ["«Allah'ın sizi bağışlamasını sevmez misiniz?»", "«Parayla ödüllendirileceksiniz»", "«Sizi güçlü kılar»", "«Sizi davadan kurtarır»"], "«Affetsinler ve hoş görsünler. Allah'ın sizi bağışlamasını sevmez misiniz? Allah bağışlayandır, merhamet edendir»."),
"virtues_083": ("7:199 ayeti hangi üç talimatı bir araya getirir?", ["Kolaylığı almak, iyiliği emretmek ve cahillerden yüz çevirmek", "Savaşmak, kaçmak, susmak", "Yemek, içmek, uyumak", "Saymak, yazmak, okumak"], "«Affı (kolaylığı) al, iyiliği emret ve cahillerden yüz çevir»."),
"virtues_084": ("Kur'an incitici sözler ve imtihan karşısında hangi tutumu tavsiye eder?", ["Sabır ve takvayı: bu azmi gerektiren işlerdendir", "Anında karşılık vermeyi", "Büsbütün çekilmeyi", "Küçümseyen sessizliği"], "«Sizden önce kendilerine Kitap verilenlerden çok incitici sözler işiteceksiniz. Sabreder ve sakınırsanız, bu azmi gerektiren işlerdendir»."),
"virtues_085": ("Kur'an sabrı ve bağışlamayı nasıl niteler?", ["Azmi gerektiren işlerdendir", "Zayıflıktır", "İsteğe bağlıdır", "Sadece âlimler içindir"], "«Kim sabreder ve bağışlarsa, şüphesiz bu azmi gerektiren işlerdendir»."),
"virtues_086": ("Kur'an'a göre namaz kimlere ağır gelmez?", ["Allah'a huşû duyanlara (haşi'în)", "Zenginlere", "Âlimlere", "Yolculara"], "«Sabır ve namazla yardım isteyin: şüphesiz bu, huşû duyanlardan başkasına ağır gelir»."),
"virtues_087": ("Kur'an hoşlanılan ve hoşlanılmayan şeyler hakkında neyi hatırlatır?", ["Hoşlanmadığınız bir şey sizin için hayırlı, sevdiğiniz bir şey şerli olabilir", "Sevdiğin her zaman hayırlıdır", "Hoşlanmadığın her zaman şerlidir", "İnsan hayrı hep bilir"], "«Hoşlanmadığınız bir şey sizin için hayırlı olabilir; sevdiğiniz bir şey de sizin için şerli olabilir. Allah bilir, siz bilmezsiniz»."),
"virtues_088": ("Kur'an Allah'tan korkana çıkış ve rızık konusunda ne vaat eder?", ["Bir çıkış ve ummadığı yerden rızık", "Anında zenginlik", "Uzun bir yolculuk", "Bir makam"], "«Kim Allah'tan korkarsa, Allah ona bir çıkış yolu yaratır ve onu ummadığı yerden rızıklandırır»."),
"virtues_089": ("Kur'an Allah'a şükürle birlikte hangi şükrü emreder?", ["Ana babaya şükrü", "Efendiye şükrü", "Komşuya şükrü", "Krala şükrü"], "«Bana ve ana babana şükret: dönüş banadır»."),
"virtues_090": ("Kur'an ana babaya itaate hangi sınırı koyar?", ["Allah'a ortak koşmayı emrederlerse itaat edilmez", "Asla itaat edilmez", "Her şeyde itaat edilir", "Sadece yolculukta itaat edilir"], "«Eğer seni, hakkında bilgin olmayan bir şeyi bana ortak koşman için zorlarlarsa onlara itaat etme; ama dünyada onlara iyilikle sahip çık»."),
"virtues_091": ("Kur'an ana baba ve zürriyet hakkında hangi duayı öğretir?", ["Nimete şükretmeyi, salih amel işlemeyi ve zürriyetin ıslahını", "Zenginlik istemeyi", "Uzun yolculuk istemeyi", "Makam istemeyi"], "«Rabbim! Bana ve ana babama verdiğin nimete şükretmemi ve razı olacağın salih amel işlememi bana ilham et; zürriyetimi de benim için ıslah et»."),
"virtues_092": ("«Rahman'ın kulları» aileleri hakkında ne ister?", ["Göz aydınlığı olmalarını ve takva sahiplerine önder olmayı", "Zengin olmalarını", "Kalabalık olmalarını", "Yolculuk etmelerini"], "«Rabbimiz! Eşlerimizden ve zürriyetimizden bize göz aydınlığı bağışla ve bizi takva sahiplerine önder kıl»."),
"virtues_093": ("«Rahman'ın kulları» boş şeyle karşılaştıklarında nasıl davranır?", ["Vakarla geçip giderler", "Dinlemek için dururlar", "Sert karşılık verirler", "Onu yazarlar"], "«Onlar yalan yere şahitlik etmezler ve boş sözle karşılaştıklarında vakarla geçip giderler»."),
"virtues_094": ("Kur'an bir mecliste yer istendiğinde ne emreder?", ["Yer açmayı: Allah size yer açar", "Sıkışık kalmayı", "Çıkmayı", "Susmayı"], "«Ey iman edenler! Size “meclislerde yer açın” denildiğinde yer açın: Allah da size genişlik versin»."),
"virtues_095": ("Tevbe suresinde Kur'an kimlerle beraber olmayı emreder?", ["Sadıklarla", "Güçlülerle", "Zenginlerle", "Yolcularla"], "«Ey iman edenler! Allah'tan korkun ve sadıklarla beraber olun»."),
"virtues_096": ("Kehf suresinde Kur'an Peygambere ﷺ kimlerle sabretmesini emreder?", ["Sabah akşam Rablerinin rızasını dileyerek O'na dua edenlerle", "Kabile reisleriyle", "Zengin tüccarlarla", "Şairlerle"], "«Sabah akşam Rablerinin rızasını dileyerek O'na dua edenlerle birlikte nefsini sabırlı tut; gözlerin onlardan başkasına kaymasın»."),
"virtues_097": ("Kur'an neyde yardımlaşmayı emreder, neyde yasaklar?", ["İyilik ve takvada yardımlaşmayı; günah ve düşmanlıkta yasaklamayı", "Her şeyde yardımlaşmayı", "Hiç yardımlaşmamayı", "Sadece ailede yardımlaşmayı"], "«İyilik ve takva üzere yardımlaşın; günah ve düşmanlık üzere yardımlaşmayın»."),
"virtues_098": ("Kur'an yapılan ahit ve pekiştirilen yeminler hakkında ne emreder?", ["Ahdi yerine getirmeyi ve pekiştirdikten sonra yeminleri bozmamayı", "Yeniden pazarlık etmeyi", "Unutmayı", "Gizlemeyi"], "«Antlaşma yaptığınızda Allah'ın ahdini yerine getirin ve pekiştirdikten sonra yeminlerinizi bozmayın»."),
"virtues_099": ("Buhari'nin rivayet ettiği bir hadise göre bir kişinin imanı ne zaman kâmil olur?", ["Kendisi için sevdiğini kardeşi için de sevdiğinde", "Bütün yıl oruç tuttuğunda", "Bütün malını verdiğinde", "Mekke'ye gittiğinde"], "«Sizden biriniz, kendisi için sevdiğini kardeşi için de sevmedikçe iman etmiş olmaz»."),
"virtues_100": ("Kur'an fısıldaşmalarda hangi durumlarda hayır görür?", ["Sadaka, iyilik veya insanlar arasını düzeltmeyi emredende", "İş görüşmesinde", "Yolculuk hazırlığında", "Haber aktarmada"], "«Onların fısıldaşmalarının çoğunda hayır yoktur; ancak sadakayı, iyiliği veya insanların arasını düzeltmeyi emreden hariç»."),
}
